Create businesses/horizen-zkverify/solana-trader/scripts/scanner.py.

This module reads the shared Nansen cache (written by base-trader) and enriches candidates with flow intelligence. It does NOT write the cache — only the base-trader scanner writes it.

Implement these functions:

```python
import json, os, time, requests
from pathlib import Path

SHARED_CACHE = Path(__file__).parent.parent.parent / 'shared' / 'nansen_cache.json'
FLOW_CACHE_FILE = Path(__file__).parent.parent / 'data' / 'flow_intel_cache.json'
FLOW_CACHE_TTL = 1800  # 30 min
WSOL_ADDRESS = 'So11111111111111111111111111111111111111112'

def _headers():
    return {'apikey': os.environ['NANSEN_API_KEY'], 'Content-Type': 'application/json'}

def get_sol_price_usd() -> float:
    """Fetch SOL/USD from DexScreener using WSOL address. Fallback: 130.0."""
    try:
        r = requests.get(
            f'https://api.dexscreener.com/latest/dex/tokens/{WSOL_ADDRESS}',
            headers={'Accept': 'application/json'}, timeout=10)
        if r.status_code == 200:
            pairs = [p for p in r.json().get('pairs', []) if p.get('chainId') == 'solana']
            if pairs:
                best = max(pairs, key=lambda p: float(p.get('liquidity', {}).get('usd', 0) or 0))
                price = float(best.get('priceUsd', 0) or 0)
                if price > 0:
                    return price
    except Exception:
        pass
    return 130.0

def get_btc_4h_change() -> float:
    """Get BTC 4h price change %. Returns 0.0 on error."""
    try:
        r = requests.get(
            'https://api.coingecko.com/api/v3/coins/bitcoin/market_chart',
            params={'vs_currency': 'usd', 'days': '1', 'interval': 'hourly'},
            timeout=10)
        if r.status_code == 200:
            prices = r.json().get('prices', [])
            if len(prices) >= 5:
                old = prices[-5][1]
                new = prices[-1][1]
                return (new - old) / old * 100
    except Exception:
        pass
    return 0.0

def load_candidate_tokens(config: dict) -> list:
    """Load Solana tokens from shared Nansen cache, apply client-side quality filters.
    Returns list of dicts with token data."""
    if not SHARED_CACHE.exists():
        print('[SCANNER] Shared cache not found — base-trader must run first')
        return []
    try:
        raw = json.loads(SHARED_CACHE.read_text())
    except Exception as e:
        print(f'[SCANNER] Cache read error: {e}')
        return []

    stablecoins = set(s.upper() for s in config.get('stablecoin_symbols', []))
    min_liq = config.get('min_liquidity_usd', 100000)
    min_mc = config.get('min_market_cap_usd', 5000000)
    max_mc = config.get('max_market_cap_usd', 500000000)
    min_age = config.get('min_token_age_days', 30)

    candidates = []
    for addr, item in raw.items():
        if item.get('chain') != 'solana':
            continue
        sym = item.get('token_symbol', '').upper()
        if sym in stablecoins:
            continue
        mc = item.get('market_cap_usd', 0) or 0
        liq = item.get('liquidity', 0) or 0
        age = item.get('token_age_days', 0) or 0
        nf = item.get('netflow', 0) or 0
        if mc < min_mc or mc > max_mc:
            continue
        if liq < min_liq:
            continue
        if age < min_age:
            continue
        candidates.append({
            'symbol': sym,
            'address': addr,
            'chain': 'solana',
            'market_cap_usd': mc,
            'liquidity_usd': liq,
            'token_age_days': age,
            'netflow_usd': nf,
            'price_usd': item.get('price_usd', 0),
            'volume_usd': item.get('volume', 0),
        })
    # Sort by netflow descending
    candidates.sort(key=lambda x: x['netflow_usd'], reverse=True)
    print(f'[SCANNER] {len(candidates)} Solana candidates after filtering')
    return candidates

def get_flow_intelligence(token_address: str) -> dict:
    """Fetch flow intelligence for a token. Cached 30 min per token."""
    cache = {}
    if FLOW_CACHE_FILE.exists():
        try:
            cache = json.loads(FLOW_CACHE_FILE.read_text())
        except Exception:
            cache = {}
    addr = token_address.lower()
    entry = cache.get(addr, {})
    if entry and time.time() - entry.get('ts', 0) < FLOW_CACHE_TTL:
        return entry.get('data', {})
    # Fetch fresh
    try:
        r = requests.post(
            'https://api.nansen.ai/api/v1/tgm/flow-intelligence',
            headers=_headers(),
            json={'token_address': token_address, 'chain': 'solana'},
            timeout=30)
        if r.status_code == 200:
            items = r.json().get('data', [])
            data = items[0] if items else {}
            cache[addr] = {'ts': time.time(), 'data': data}
            FLOW_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
            FLOW_CACHE_FILE.write_text(json.dumps(cache))
            return data
    except Exception as e:
        print(f'[SCANNER] flow-intelligence error for {token_address}: {e}')
    return {}
```

